import{_ as e,o,c as d,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Exponentiation-Operator.md","filePath":"manual-zh/Matrix-Exponentiation-Operator.md","lastUpdated":1785684581000}'),c={name:"manual-zh/Matrix-Exponentiation-Operator.md"};function r(n,t,i,l,p,_){return o(),d("div",null,[...t[0]||(t[0]=[a('<h4 id="_16-4-1-7-矩阵乘方运算符" tabindex="-1">16.4.1.7 矩阵乘方运算符 <code>**</code> <a class="header-anchor" href="#_16-4-1-7-矩阵乘方运算符" aria-label="Permalink to &quot;16.4.1.7 矩阵乘方运算符 `**`&quot;">​</a></h4><p>当 <code>A</code> 为方阵且 <code>B</code> 为整数标量时，<code>A**B</code> 的结果定义如下：</p><ul><li>当 <code>B &gt; 0</code> 时，<code>A**B</code> 即 <code>A*…*A</code>，其中共有 <code>B</code> 个 “A”。（PSPP 对较大的 <code>B</code> 采用平方求幂法高效地实现。）</li><li>当 <code>B &lt; 0</code> 时，<code>A**B</code> 即 <code>INV(A**(-B))</code>。</li><li>当 <code>B = 0</code> 时，<code>A**B</code> 为单位矩阵。</li></ul><p>如果 <code>A</code> 不是方阵，或 <code>B</code> 不是整数，PSPP 会报错。</p><p>示例：</p><table tabindex="0"><thead><tr><th>{2, 5; 1, 4}**3</th><th>⇒</th><th>{48, 165; 33, 114}</th></tr></thead><tbody><tr><td>{2, 5; 1, 4}**0</td><td>⇒</td><td>{1, 0; 0, 1}</td></tr><tr><td>10*{4, 7; 2, 6}**-1</td><td>⇒</td><td>{6, -7; -2, 4}</td></tr></tbody></table>',6)])])}const B=e(c,[["render",r]]);export{h as __pageData,B as default};
